const assert=require('node:assert/strict');
const fs=require('node:fs');const path=require('node:path');const http=require('node:http');
const {app,BrowserWindow,ipcMain}=require('electron');
const {TabManager}=require('../../dist/main/tab-manager.js');
const {IPC_CHANNELS,isTabsCommand}=require('../../dist/shared/ipc-contract.js');
const directory=process.argv.at(-1);app.setPath('userData',path.join(directory,'profile'));app.on('window-all-closed',()=>{});
const until=async(probe,label)=>{for(let end=Date.now()+12000;Date.now()<end;){if(await probe())return;await new Promise(resolve=>setTimeout(resolve,25));}throw new Error('Timed out: '+label);};
app.whenReady().then(async()=>{
  const server=http.createServer((req,res)=>{res.setHeader('Content-Type',req.url.startsWith('/api/')?'application/json':'text/html');res.end(req.url.startsWith('/api/')?'{}':'<!doctype html><title>Annotation page</title><p id="selection">A selected passage.</p>');});
  await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));const origin=`http://127.0.0.1:${server.address().port}`;
  const blank=path.join(directory,'blank.html');fs.writeFileSync(blank,'<!doctype html>');const preload=path.resolve(__dirname,'../../dist/preload/preload.js');
  const manager=new TabManager({allowed:{origins:new Set([origin]),localFiles:new Set()},preloadPath:preload,loadingHtmlPath:()=>blank,recoveryHtmlPath:()=>blank,theme:()=> 'light',openWindow:()=>{}});
  manager.setBrowserUrl(origin+'/browser');manager.setNewTabUrl(origin+'/new-tab');
  ipcMain.handle(IPC_CHANNELS.getTabsState,event=>manager.stateFor(event.sender));ipcMain.handle(IPC_CHANNELS.tabsCommand,(event,command)=>isTabsCommand(command)&&manager.handleCommand(event.sender,command));
  const window=new BrowserWindow({show:false,width:1300,height:850,webPreferences:{preload,contextIsolation:true,sandbox:true}});window.setOpacity(0);manager.attach(window);await window.loadURL(origin+'/dashboard');window.showInactive();
  await manager.handleCommand(window.webContents,{type:'browser',url:origin+'/page'});
  const host=manager.hosts.get(window.id);const tab=host.tabs.find(tab=>tab.id===host.activeId);
  await until(()=>!host.pending&&tab.browser?.ready&&!tab.browser.contents.isLoading(),'native page ready');
  const chrome=tab.contents,page=tab.browser.contents;const initial=tab.browser.view.getBounds();
  const shell=command=>manager.shellCommand(host,{command,targetId:tab.id,generation:tab.generation,revision:host.presentationRevision});
  assert.equal(await shell({type:'browser-organization',open:true}),true,'persistent toolbar routes the new control');
  assert.equal(tab.browser.view.getBounds().width,initial.width-360);assert.equal(tab.browser.view.getBounds().x,initial.x);
  const target={kind:'text',url:origin+'/page',title:'Annotation page',quote:'A selected passage.',prefix:'',suffix:''};
  assert.equal(await manager.handleCommand(page,{type:'browser-organization-target',target}),false,'website cannot issue trusted commands');
  assert.equal(await manager.handleCommand(chrome,{type:'browser-organization-target',target:{...target,url:origin+'/other'}}),false);
  assert.equal(await manager.handleCommand(chrome,{type:'browser-organization-target',target}),true);
  assert.equal(await manager.handleCommand(chrome,{type:'browser-organization-markers',items:[{id:'thread-1',target}]}),true);
  await until(()=>page.executeJavaScript('CSS.highlights.get("breadboard-community")?.size === 1'),'shared text marker painted');
  assert.equal(await manager.handleCommand(chrome,{type:'browser-organization-enabled',enabled:false}),true);
  assert.equal(tab.browser.organizationOpen,false);assert.equal(tab.browser.view.getBounds().width,initial.width);
  await until(()=>page.executeJavaScript('!document.querySelector("[data-breadboard-selection=community]")'),'markers removed when disabled');
  assert.equal(await shell({type:'browser-organization',open:true}),false);
  await manager.handleCommand(chrome,{type:'browser-organization-enabled',enabled:true});
  await manager.handleCommand(chrome,{type:'browser-organization-target',target});
  await manager.handleCommand(chrome,{type:'browser-terminal',open:true});assert.equal(tab.browser.organizationOpen,false);
  await manager.handleCommand(chrome,{type:'browser-organization-target',target});assert.equal(tab.browser.terminalOpen,false);
  await page.executeJavaScript('history.pushState({},"","/next")');await until(()=>tab.url===origin+'/next','SPA navigation');
  assert.equal(tab.browser.annotationTarget,undefined);assert.deepEqual(tab.browser.annotationMarkers,[]);
  assert.equal(await manager.handleCommand(chrome,{type:'browser-organization-target',target}),false,'old page selection rejected');
  host.privateBrowsing=true;assert.equal(await shell({type:'browser-organization',open:true}),false);host.privateBrowsing=false;
  // The real selection popover carries a main-process-owned target.
  const entry={id:'selection1',quote:'A selected passage.',prefix:'',suffix:'',start:0,end:19};
  await until(()=>Boolean(tab.browser.highlights),'highlights service');
  manager.openSelectionPopover(host,tab,entry,{x:50,y:90});
  await until(()=>host.selectionPopover&&!host.selectionPopover.contents.isLoading(),'selection popover');
  const popup=host.selectionPopover.contents;assert.equal(new URL(popup.getURL()).searchParams.get('community'),'1');
  assert.equal(await manager.handleCommand(popup,{type:'browser-organization-selection'}),true);
  assert.equal(tab.browser.annotationTarget.quote,'A selected passage.');assert.equal(tab.browser.annotationTarget.url,origin+'/next');
  fs.writeFileSync(path.join(directory,'passed.json'),JSON.stringify({passed:true}));
  console.log('Right-side bounds, toolbar routing, settings, untrusted callers, SPA navigation, private mode and selection comments passed.');
  for(const win of BrowserWindow.getAllWindows())win.destroy();server.closeAllConnections();server.close();app.exit(0);
}).catch(error=>{console.error(error);app.exit(1);});
